import logo from './logo.svg';
import './App.css';
import LightPillar from './LightPillar';

function App() {
  return (
    <div className="App">

      <div id="pillar" style={{ width: '100%', height: '100vh', position: 'absolute' }}>
        <LightPillar
          topColor="#748cec"
          bottomColor="#ce466f"
          intensity={1}
          rotationSpeed={0.3}
          glowAmount={0.002}
          pillarWidth={3}
          pillarHeight={0.4}
          noiseIntensity={0.5}
          pillarRotation={25}
          interactive={false}
          mixBlendMode="screen"
          quality="high"
        />
      </div>
      <div id="hero">
        <div id="navbar">
          <div id="logo">
            <img src="Logo.svg" width="60" height="60"/>
          </div>
          <div id="elements">

          </div>
        </div>
      </div>
      <svg width="106" height="105" viewBox="0 0 106 105" fill="none" xmlns="http://www.w3.org/2000/svg">
<path d="M40.3975 70L46.7015 47.6H50.5415L56.9095 70H54.1895L49.1335 51.632L48.8775 49.936C48.8562 49.808 48.7815 49.744 48.6535 49.744C48.5468 49.744 48.4828 49.808 48.4615 49.936L48.1735 51.632L43.1175 70H40.3975ZM43.8535 64.016L44.5575 61.648H52.7495L53.4535 64.016H43.8535ZM43.0535 49.936V47.6H47.5655V49.936H43.0535Z" fill="white"/>
<path d="M53.7342 73V56.2H55.7262V71.128H61.7022V73H53.7342Z" fill="white"/>
</svg>

    </div>

  );
}

export default App;
